-- Synthetic accounts only, always rolled back. Also runnable on hosted PostgreSQL.
begin;
create schema fk_outcome_test;
grant usage on schema fk_outcome_test to authenticated;
create function fk_outcome_test.ok(v boolean,label text) returns void language plpgsql as $$
begin if v is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function fk_outcome_test.rejected(statement text) returns boolean language plpgsql as $$
begin execute statement; return false; exception when others then return true; end $$;
grant execute on all functions in schema fk_outcome_test to authenticated;
insert into auth.users(id) values('e1111111-1111-4111-8111-111111111111'),('e2222222-2222-4222-8222-222222222222'),('e3333333-3333-4333-8333-333333333333');
insert into auth.sessions(id,user_id) select id,id from auth.users where id in ('e1111111-1111-4111-8111-111111111111','e2222222-2222-4222-8222-222222222222','e3333333-3333-4333-8333-333333333333');
insert into folkoop_private.pilots(user_id) select id from auth.users where id in ('e1111111-1111-4111-8111-111111111111','e2222222-2222-4222-8222-222222222222','e3333333-3333-4333-8333-333333333333');
set local role authenticated;
select set_config('request.jwt.claim.sub','e1111111-1111-4111-8111-111111111111',true);
select set_config('request.jwt.claims','{"sub":"e1111111-1111-4111-8111-111111111111","session_id":"e1111111-1111-4111-8111-111111111111"}',true);
select public.fk_save_profile('Synthetic organizer','','',true);
select set_config('test.meeting',public.fk_create_cooperation('project','Synthetic outcome test','Synthetic only','Göteborg',null,'')::text,true);
select public.fk_save_meeting_terms(current_setting('test.meeting')::uuid,0,now()+interval '1 day',now()+interval '25 hours','Synthetic room','Free',2,4,null,null);
select public.fk_respond_meeting(current_setting('test.meeting')::uuid,1,'attendee',true);
select fk_outcome_test.ok(fk_outcome_test.rejected(format('select public.fk_report_meeting_outcome(%L,1,''held'','''')',current_setting('test.meeting'))),'cannot report a future meeting');
select fk_outcome_test.ok(fk_outcome_test.rejected(format('select public.fk_repeat_meeting(%L,1,now()+interval ''2 days'',now()+interval ''49 hours'')',current_setting('test.meeting'))),'cannot repeat before end');
select set_config('request.jwt.claim.sub','e2222222-2222-4222-8222-222222222222',true);
select set_config('request.jwt.claims','{"sub":"e2222222-2222-4222-8222-222222222222","session_id":"e2222222-2222-4222-8222-222222222222"}',true);
select public.fk_save_profile('Synthetic participant','','',true);
select public.fk_join_cooperation(current_setting('test.meeting')::uuid);
select public.fk_respond_meeting(current_setting('test.meeting')::uuid,1,'attendee',true);
reset role;
-- Advance only fixture event times, never a real meeting or the server clock.
update public.fk_meeting_terms set starts_at=now()-interval '2 hours',ends_at=now()-interval '1 hour' where cooperation_id=current_setting('test.meeting')::uuid;
set local role authenticated;
select fk_outcome_test.ok(public.fk_meeting_outcome_snapshot(current_setting('test.meeting')::uuid)->>'state'='unreported','elapsed time does not imply success');
select public.fk_report_meeting_outcome(current_setting('test.meeting')::uuid,1,'held','Useful practice');
select public.fk_report_meeting_outcome(current_setting('test.meeting')::uuid,1,'held','Useful practice');
select fk_outcome_test.ok((select count(*)=1 from public.fk_meeting_outcomes where cooperation_id=current_setting('test.meeting')::uuid),'repeat report idempotent');
select fk_outcome_test.ok(public.fk_meeting_outcome_snapshot(current_setting('test.meeting')::uuid)->>'state'='self_reported','participant alone not confirmed outcome');
select fk_outcome_test.ok(fk_outcome_test.rejected(format('select public.fk_repeat_meeting(%L,1,now()+interval ''2 days'',now()+interval ''49 hours'')',current_setting('test.meeting'))),'member cannot repeat as organizer');
select fk_outcome_test.ok(fk_outcome_test.rejected('update public.fk_meeting_outcomes set user_id=''e1111111-1111-4111-8111-111111111111'''),'direct write denied');
select set_config('request.jwt.claim.sub','e1111111-1111-4111-8111-111111111111',true);
select set_config('request.jwt.claims','{"sub":"e1111111-1111-4111-8111-111111111111","session_id":"e1111111-1111-4111-8111-111111111111"}',true);
select public.fk_report_meeting_outcome(current_setting('test.meeting')::uuid,1,'held','');
select fk_outcome_test.ok(public.fk_meeting_outcome_snapshot(current_setting('test.meeting')::uuid)->>'state'='participant_confirmed','organizer and participant agree');
select public.fk_report_meeting_outcome(current_setting('test.meeting')::uuid,1,'not_held','Correction');
select fk_outcome_test.ok(public.fk_meeting_outcome_snapshot(current_setting('test.meeting')::uuid)->>'state'='unclear','disagreement overrides positive count');
select public.fk_report_meeting_outcome(current_setting('test.meeting')::uuid,1,'unsure','');
select fk_outcome_test.ok(public.fk_meeting_outcome_snapshot(current_setting('test.meeting')::uuid)->>'state'='unclear','uncertainty not counted as success');
select public.fk_report_meeting_outcome(current_setting('test.meeting')::uuid,1,'withdrawn','remove this note');
select fk_outcome_test.ok(public.fk_meeting_outcome_snapshot(current_setting('test.meeting')::uuid)->>'state'='self_reported','withdrawal removes corroboration');
select fk_outcome_test.ok((select note='' from public.fk_meeting_outcomes where cooperation_id=current_setting('test.meeting')::uuid and user_id=auth.uid()),'withdrawal clears note');
select fk_outcome_test.ok(fk_outcome_test.rejected(format('select public.fk_save_meeting_terms(%L,1,now()+interval ''2 days'',now()+interval ''49 hours'',''Room'','''',1,5,null,null)',current_setting('test.meeting'))),'past event cannot be overwritten');
select fk_outcome_test.ok(fk_outcome_test.rejected(format('select public.fk_repeat_meeting(%L,2,now()+interval ''2 days'',now()+interval ''49 hours'')',current_setting('test.meeting'))),'stale repeat version denied');
select fk_outcome_test.ok(fk_outcome_test.rejected(format('select public.fk_repeat_meeting(%L,1,now()-interval ''2 days'',now()-interval ''1 day'')',current_setting('test.meeting'))),'invalid new date rolls back creation');
select set_config('test.next',public.fk_repeat_meeting(current_setting('test.meeting')::uuid,1,now()+interval '2 days',now()+interval '49 hours')::text,true);
select fk_outcome_test.ok(public.fk_repeat_meeting(current_setting('test.meeting')::uuid,1,now()+interval '2 days',now()+interval '49 hours')::text=current_setting('test.next'),'retry returns same next meeting');
select fk_outcome_test.ok((select count(*)=1 from public.fk_cooperation_members where cooperation_id=current_setting('test.next')::uuid),'only organizer belongs to next meeting');
select fk_outcome_test.ok((select count(*)=0 from public.fk_meeting_responses where cooperation_id=current_setting('test.next')::uuid),'no consent copied, including organizer');
select fk_outcome_test.ok((select count(*)=0 from public.fk_meeting_outcomes where cooperation_id=current_setting('test.next')::uuid),'no outcomes copied');
select fk_outcome_test.ok((select version=1 and facilitator_id is null and opener_id is null and place='Synthetic room' from public.fk_meeting_terms where cooperation_id=current_setting('test.next')::uuid),'new terms preserve place but not role assignments');
select fk_outcome_test.ok(public.fk_meeting_outcome_snapshot(current_setting('test.next')::uuid)->>'previous_id'=current_setting('test.meeting'),'permitted previous link');
select fk_outcome_test.ok(fk_outcome_test.rejected(format('select public.fk_report_meeting_outcome(%L,1,''held'','''')',current_setting('test.next'))),'new meeting does not inherit reporting eligibility');
select set_config('request.jwt.claim.sub','e3333333-3333-4333-8333-333333333333',true);
select set_config('request.jwt.claims','{"sub":"e3333333-3333-4333-8333-333333333333","session_id":"e3333333-3333-4333-8333-333333333333"}',true);
select public.fk_save_profile('Synthetic outsider','','',true);
select fk_outcome_test.ok((select count(*)=0 from public.fk_meeting_outcomes),'outsider RLS hides outcomes');
select fk_outcome_test.ok(fk_outcome_test.rejected(format('select public.fk_meeting_outcome_snapshot(%L)',current_setting('test.meeting'))),'outsider cannot query snapshot');
select public.fk_join_cooperation(current_setting('test.meeting')::uuid);
select fk_outcome_test.ok(fk_outcome_test.rejected(format('select public.fk_report_meeting_outcome(%L,1,''held'','''')',current_setting('test.meeting'))),'late joiner without attendance consent cannot report');
select fk_outcome_test.ok(public.fk_meeting_outcome_snapshot(current_setting('test.meeting')::uuid)->>'next_id' is null,'next private meeting link hidden from nonmember');
select set_config('request.jwt.claims','{}',true);
select fk_outcome_test.ok(fk_outcome_test.rejected(format('select public.fk_report_meeting_outcome(%L,1,''held'','''')',current_setting('test.meeting'))),'missing session denied');
reset role;
select fk_outcome_test.ok(not has_function_privilege('anon','public.fk_report_meeting_outcome(uuid,integer,text,text)','execute'),'anonymous RPC denied');
select fk_outcome_test.ok(not has_function_privilege('authenticated','folkoop_private.account_closure_inventory_v3(uuid)','execute'),'closure inventory remains private');
select fk_outcome_test.ok((folkoop_private.account_closure_inventory_v3('e2222222-2222-4222-8222-222222222222')->'user_scoped'->>'meeting_outcomes')::integer=1,'export and closure inventory include outcome');
delete from auth.users where id='e2222222-2222-4222-8222-222222222222';
select fk_outcome_test.ok((select count(*)=0 from public.fk_meeting_outcomes where user_id='e2222222-2222-4222-8222-222222222222'),'closing synthetic participant removes their outcome');
select fk_outcome_test.ok((select count(*)=2 from public.fk_cooperations where id in (current_setting('test.meeting')::uuid,current_setting('test.next')::uuid)),'closure preserves both shared meetings');
rollback;
